{
  "name": "@bytesbrains/opencode-cruise",
  "version": "0.1.2",
  "description": "BytesBrains Cruise plugin for OpenCode — budgets, lanes, and OpenAI-compatible routing via the Cruise gateway.",
  "license": "Apache-2.0",
  "type": "module",
  "homepage": "https://bytesbrains.com/cruise",
  "repository": {
    "type": "git",
    "url": "git+https://gitlab.com/cruise-oss/cruise-opencode.git"
  },
  "bugs": {
    "url": "https://gitlab.com/cruise-oss/cruise-opencode/-/issues"
  },
  "keywords": [
    "opencode",
    "cruise",
    "bytesbrains",
    "llm",
    "openai-compatible",
    "byok",
    "plugin"
  ],
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "NOTICE"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run",
    "rehearse:demo": "node scripts/rehearse-demo.mjs",
    "pack:check": "node scripts/pack-check.mjs",
    "prepack": "npm run build"
  },
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.4.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.31",
    "@types/node": "^26.6.1",
    "typescript": "^7.0.2",
    "vitest": "^5.0.1"
  },
  "engines": {
    "node": ">=22"
  }
}
